[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Aid Alliance — Together We Respond</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap" rel="stylesheet">
  <script>
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            brand: {
              red: '#C41E3A',
              'red-dark': '#A01830',
              'red-light': '#F9E0E4',
              navy: '#1B3A5C',
              'navy-dark': '#132A44',
              'navy-light': '#E8EEF4',
              gray: '#6B7280',
              'gray-light': '#F8F9FA',
              'gray-warm': '#F3F1EE',
            }
          },
          fontFamily: {
            heading: ['"Plus Jakarta Sans"', 'system-ui', 'sans-serif'],
            body: ['Inter', 'system-ui', 'sans-serif'],
          }
        }
      }
    }
  </script>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', system-ui, sans-serif; color: #1F2937; }

    /* Counter animation */
    .stat-number { font-variant-numeric: tabular-nums; }

    /* Accordion */
    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.4s ease-out, padding 0.3s ease;
    }
    .accordion-content.open {
      max-height: 300px;
      padding-top: 0.75rem;
      padding-bottom: 0.75rem;
    }
    .accordion-icon {
      transition: transform 0.3s ease;
    }
    .accordion-icon.rotated {
      transform: rotate(180deg);
    }

    /* Mobile menu */
    .mobile-menu {
      transform: translateX(100%);
      transition: transform 0.35s ease-out;
    }
    .mobile-menu.open {
      transform: translateX(0);
    }
    .mobile-overlay {
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.35s ease;
    }
    .mobile-overlay.open {
      opacity: 1;
      pointer-events: auto;
    }

    /* Modal */
    .modal-backdrop {
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.3s ease;
    }
    .modal-backdrop.open {
      opacity: 1;
      pointer-events: auto;
    }
    .modal-panel {
      transform: scale(0.95) translateY(10px);
      opacity: 0;
      transition: transform 0.3s ease, opacity 0.3s ease;
    }
    .modal-backdrop.open .modal-panel {
      transform: scale(1) translateY(0);
      opacity: 1;
    }

    /* News carousel */
    .carousel-track {
      transition: transform 0.5s ease-out;
    }

    /* Scroll animations */
    .fade-in-up {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 0.6s ease-out, transform 0.6s ease-out;
    }
    .fade-in-up.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* Header scroll */
    .header-scrolled {
      box-shadow: 0 1px 12px rgba(0,0,0,0.08);
      background: rgba(255,255,255,0.97);
      backdrop-filter: blur(8px);
    }

    /* Donation amount buttons */
    .amount-btn {
      transition: all 0.15s ease;
    }
    .amount-btn:hover {
      border-color: #C41E3A;
      background: #F9E0E4;
    }
    .amount-btn.selected {
      border-color: #C41E3A;
      background: #C41E3A;
      color: white;
    }

    /* Smooth focus */
    a:focus-visible, button:focus-visible {
      outline: 2px solid #C41E3A;
      outline-offset: 2px;
      border-radius: 2px;
    }

    /* Program icon circles */
    .program-icon {
      transition: background 0.2s ease, transform 0.2s ease;
    }
    .program-item:hover .program-icon {
      background: #C41E3A;
      transform: scale(1.05);
    }
  </style>
</head>
<body class="bg-white">

  <!-- ========== HEADER ========== -->
  <header id="site-header" class="fixed top-0 left-0 right-0 z-50 bg-white transition-all duration-300">
    <!-- Utility bar -->
    <div class="hidden md:block bg-brand-navy text-white text-xs">
      <div class="max-w-7xl mx-auto px-6 py-1.5 flex justify-end items-center gap-4">
        <a href="#" class="hover:text-brand-red-light transition-colors">Sign In</a>
        <span class="opacity-30">|</span>
        <a href="#" class="hover:text-brand-red-light transition-colors">Contact Us</a>
        <span class="opacity-30">|</span>
        <a href="#" class="hover:text-brand-red-light transition-colors">Espa&ntilde;ol</a>
      </div>
    </div>
    <!-- Main nav -->
    <nav class="max-w-7xl mx-auto px-6 py-3 flex items-center justify-between">
      <a href="#" class="flex items-center gap-2.5 shrink-0">
        <div class="w-9 h-9 bg-brand-red rounded-lg flex items-center justify-center">
          <i data-lucide="heart-handshake" class="w-5 h-5 text-white"></i>
        </div>
        <span class="font-heading font-800 text-lg text-brand-navy leading-tight">Global Aid<br class="hidden sm:inline"> Alliance</span>
      </a>
      <!-- Desktop nav links -->
      <div class="hidden lg:flex items-center gap-7 text-sm font-medium text-gray-700">
        <a href="#mission" class="hover:text-brand-red transition-colors">About Us</a>
        <a href="#programs" class="hover:text-brand-red transition-colors">Disaster Relief</a>
        <a href="#programs" class="hover:text-brand-red transition-colors">Programs &amp; Services</a>
        <a href="#get-involved" class="hover:text-brand-red transition-colors">Volunteer</a>
        <a href="#" class="hover:text-brand-red transition-colors">Find Local Chapter</a>
      </div>
      <!-- Donate button + hamburger -->
      <div class="flex items-center gap-3">
        <button onclick="openDonateModal()" class="bg-brand-red hover:bg-brand-red-dark text-white font-semibold text-sm px-5 py-2.5 rounded-lg transition-colors">
          Donate
        </button>
        <button id="hamburger-btn" onclick="toggleMobileMenu()" class="lg:hidden p-2 -mr-2 text-gray-700" aria-label="Open menu">
          <i data-lucide="menu" class="w-6 h-6"></i>
        </button>
      </div>
    </nav>
  </header>

  <!-- Mobile overlay -->
  <div id="mobile-overlay" class="mobile-overlay fixed inset-0 bg-black/40 z-50" onclick="toggleMobileMenu()"></div>
  <!-- Mobile menu drawer -->
  <div id="mobile-menu" class="mobile-menu fixed top-0 right-0 bottom-0 w-72 bg-white z-50 shadow-2xl flex flex-col">
    <div class="flex items-center justify-between p-5 border-b">
      <span class="font-heading font-700 text-brand-navy">Menu</span>
      <button onclick="toggleMobileMenu()" class="p-1" aria-label="Close menu">
        <i data-lucide="x" class="w-5 h-5 text-gray-500"></i>
      </button>
    </div>
    <div class="flex flex-col p-5 gap-1 text-gray-700 font-medium">
      <a href="#mission" onclick="toggleMobileMenu()" class="py-2.5 px-3 rounded-lg hover:bg-gray-50 transition">About Us</a>
      <a href="#programs" onclick="toggleMobileMenu()" class="py-2.5 px-3 rounded-lg hover:bg-gray-50 transition">Disaster Relief</a>
      <a href="#programs" onclick="toggleMobileMenu()" class="py-2.5 px-3 rounded-lg hover:bg-gray-50 transition">Programs &amp; Services</a>
      <a href="#get-involved" onclick="toggleMobileMenu()" class="py-2.5 px-3 rounded-lg hover:bg-gray-50 transition">Volunteer</a>
      <a href="#" onclick="toggleMobileMenu()" class="py-2.5 px-3 rounded-lg hover:bg-gray-50 transition">Find Local Chapter</a>
    </div>
    <div class="mt-auto p-5 border-t space-y-3">
      <button onclick="openDonateModal(); toggleMobileMenu();" class="w-full bg-brand-red hover:bg-brand-red-dark text-white font-semibold py-3 rounded-lg transition-colors">Donate Now</button>
      <div class="flex justify-center gap-5 text-sm text-gray-500">
        <a href="#" class="hover:text-brand-red">Sign In</a>
        <a href="#" class="hover:text-brand-red">Contact Us</a>
        <a href="#" class="hover:text-brand-red">Espa&ntilde;ol</a>
      </div>
    </div>
  </div>

  <!-- ========== HERO ========== -->
  <section id="hero" class="relative pt-28 md:pt-36 pb-20 md:pb-28 overflow-hidden">
    <!-- Background gradient -->
    <div class="absolute inset-0 bg-gradient-to-br from-brand-navy via-brand-navy-dark to-brand-navy"></div>
    <!-- Subtle pattern overlay -->
    <div class="absolute inset-0 opacity-[0.04]" style="background-image: url('data:image/svg+xml,<svg width=&quot;60&quot; height=&quot;60&quot; viewBox=&quot;0 0 60 60&quot; xmlns=&quot;http://www.w3.org/2000/svg&quot;><circle cx=&quot;30&quot; cy=&quot;30&quot; r=&quot;1.5&quot; fill=&quot;white&quot;/></svg>');"></div>
    <!-- Red accent bar -->
    <div class="absolute bottom-0 left-0 right-0 h-1.5 bg-brand-red"></div>
    <div class="relative max-w-7xl mx-auto px-6 grid lg:grid-cols-2 gap-12 items-center">
      <div class="text-white">
        <div class="inline-flex items-center gap-2 bg-white/10 border border-white/20 rounded-full px-4 py-1.5 text-sm font-medium mb-6">
          <span class="w-2 h-2 bg-brand-red rounded-full animate-pulse"></span>
          Active Disaster Response
        </div>
        <h1 class="font-heading font-800 text-4xl sm:text-5xl lg:text-6xl leading-[1.1] mb-6">
          When Disaster Strikes,<br>
          <span class="text-brand-red">We're There</span>
        </h1>
        <p class="text-lg text-white/80 max-w-xl mb-8 leading-relaxed">
          From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.
        </p>
        <div class="flex flex-wrap gap-4">
          <button onclick="openDonateModal()" class="bg-brand-red hover:bg-brand-red-dark text-white font-semibold px-8 py-3.5 rounded-lg transition-colors text-base shadow-lg shadow-brand-red/30">
            Donate Now
          </button>
          <a href="#get-involved" class="bg-white/10 hover:bg-white/20 border border-white/30 text-white font-semibold px-8 py-3.5 rounded-lg transition-colors text-base">
            Become a Volunteer
          </a>
        </div>
      </div>
      <div class="hidden lg:block">
        <div class="relative rounded-2xl overflow-hidden shadow-2xl">
          <img src="https://images.unsplash.com/photo-1469571486292-0ba58a3f068b?w=800&h=540&fit=crop&q=80" alt="Volunteers providing disaster relief supplies to a community" class="w-full h-auto object-cover" loading="eager">
          <div class="absolute inset-0 bg-gradient-to-t from-brand-navy/40 to-transparent"></div>
        </div>
      </div>
    </div>
  </section>

  <!-- ========== MISSION ========== -->
  <section id="mission" class="py-20 md:py-28 bg-white">
    <div class="max-w-4xl mx-auto px-6 text-center fade-in-up">
      <div class="inline-flex items-center justify-center w-14 h-14 rounded-full bg-brand-red-light mb-6">
        <i data-lucide="shield-check" class="w-7 h-7 text-brand-red"></i>
      </div>
      <h2 class="font-heading font-700 text-3xl md:text-4xl text-brand-navy mb-6">Our Mission</h2>
      <p class="text-lg md:text-xl text-gray-600 leading-relaxed mb-6">
        <strong class="text-brand-navy">Global Aid Alliance prevents and alleviates human suffering</strong> in the face of emergencies by mobilizing the power of volunteers and the generosity of donors.
      </p>
      <p class="text-base text-gray-500 leading-relaxed max-w-3xl mx-auto">
        We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most &mdash; regardless of race, religion, nationality, or political affiliation. From the first hours of a disaster to the years of recovery that follow, we stand with affected communities every step of the way.
      </p>
    </div>
  </section>

  <!-- ========== IMPACT STATS ========== -->
  <section id="impact-stats" class="py-16 md:py-20 bg-brand-navy relative overflow-hidden">
    <div class="absolute inset-0 opacity-[0.03]" style="background-image: url('data:image/svg+xml,<svg width=&quot;40&quot; height=&quot;40&quot; viewBox=&quot;0 0 40 40&quot; xmlns=&quot;http://www.w3.org/2000/svg&quot;><circle cx=&quot;20&quot; cy=&quot;20&quot; r=&quot;1&quot; fill=&quot;white&quot;/></svg>');"></div>
    <div class="relative max-w-7xl mx-auto px-6">
      <div class="grid grid-cols-2 lg:grid-cols-4 gap-8 md:gap-12 fade-in-up">
        <!-- Stat 1 -->
        <div class="text-center">
          <div class="font-heading font-800 text-4xl md:text-5xl lg:text-6xl text-white mb-2 stat-number" data-target="12" data-suffix="M" data-prefix="">0</div>
          <div class="text-white/60 text-sm md:text-base font-medium">People Assisted Annually</div>
        </div>
        <!-- Stat 2 -->
        <div class="text-center">
          <div class="font-heading font-800 text-4xl md:text-5xl lg:text-6xl text-white mb-2 stat-number" data-target="50" data-suffix="K" data-prefix="">0</div>
          <div class="text-white/60 text-sm md:text-base font-medium">Active Volunteers</div>
        </div>
        <!-- Stat 3 -->
        <div class="text-center">
          <div class="font-heading font-800 text-4xl md:text-5xl lg:text-6xl text-brand-red mb-2 stat-number" data-target="190" data-suffix="" data-prefix="">0</div>
          <div class="text-white/60 text-sm md:text-base font-medium">Countries Where We've Provided Aid</div>
        </div>
        <!-- Stat 4 -->
        <div class="text-center">
          <div class="font-heading font-800 text-4xl md:text-5xl lg:text-6xl text-white mb-2 stat-number" data-target="850" data-suffix="M" data-prefix="$">0</div>
          <div class="text-white/60 text-sm md:text-base font-medium">Raised in the Last Fiscal Year</div>
        </div>
      </div>
      <p class="text-center text-white/40 text-sm mt-10 max-w-2xl mx-auto">
        These figures represent real lives changed &mdash; families sheltered after storms, blood delivered to hospitals, and communities rebuilt stronger than before.
      </p>
    </div>
  </section>

  <!-- ========== PROGRAMS ========== -->
  <section id="programs" class="py-20 md:py-28 bg-brand-gray-warm">
    <div class="max-w-4xl mx-auto px-6 fade-in-up">
      <div class="text-center mb-12">
        <h2 class="font-heading font-700 text-3xl md:text-4xl text-brand-navy mb-4">Programs &amp; Services</h2>
        <p class="text-gray-500 max-w-xl mx-auto">From rapid disaster response to long-term community health, our programs serve people where the need is greatest.</p>
      </div>
      <div class="space-y-3">
        <!-- Program 1 -->
        <div class="program-item bg-white rounded-xl border border-gray-200 overflow-hidden">
          <button onclick="toggleAccordion(this)" class="w-full flex items-center gap-4 p-5 md:p-6 text-left hover:bg-gray-50 transition-colors" aria-expanded="false">
            <div class="program-icon w-11 h-11 rounded-lg bg-brand-red-light flex items-center justify-center shrink-0">
              <i data-lucide="siren" class="w-5 h-5 text-brand-red"></i>
            </div>
            <span class="font-heading font-700 text-lg text-brand-navy flex-1">Disaster Relief</span>
            <i data-lucide="chevron-down" class="accordion-icon w-5 h-5 text-gray-400 shrink-0"></i>
          </button>
          <div class="accordion-content px-5 md:px-6 pb-0">
            <p class="text-gray-600 leading-relaxed pl-0 md:pl-15">Rapid deployment of emergency shelter, food, water, and medical supplies to communities affected by natural disasters and conflict. Our response teams are on the ground within 24 hours.</p>
          </div>
        </div>
        <!-- Program 2 -->
        <div class="program-item bg-white rounded-xl border border-gray-200 overflow-hidden">
          <button onclick="toggleAccordion(this)" class="w-full flex items-center gap-4 p-5 md:p-6 text-left hover:bg-gray-50 transition-colors" aria-expanded="false">
            <div class="program-icon w-11 h-11 rounded-lg bg-brand-red-light flex items-center justify-center shrink-0">
              <i data-lucide="droplets" class="w-5 h-5 text-brand-red"></i>
            </div>
            <span class="font-heading font-700 text-lg text-brand-navy flex-1">Blood Donation</span>
            <i data-lucide="chevron-down" class="accordion-icon w-5 h-5 text-gray-400 shrink-0"></i>
          </button>
          <div class="accordion-content px-5 md:px-6 pb-0">
            <p class="text-gray-600 leading-relaxed pl-0 md:pl-15">Operating one of the largest blood collection networks, we supply approximately 40% of the nation's blood and blood products to hospitals and medical facilities.</p>
          </div>
        </div>
        <!-- Program 3 -->
        <div class="program-item bg-white rounded-xl border border-gray-200 overflow-hidden">
          <button onclick="toggleAccordion(this)" class="w-full flex items-center gap-4 p-5 md:p-6 text-left hover:bg-gray-50 transition-colors" aria-expanded="false">
            <div class="program-icon w-11 h-11 rounded-lg bg-brand-red-light flex items-center justify-center shrink-0">
              <i data-lucide="shield-alert" class="w-5 h-5 text-brand-red"></i>
            </div>
            <span class="font-heading font-700 text-lg text-brand-navy flex-1">Emergency Preparedness</span>
            <i data-lucide="chevron-down" class="accordion-icon w-5 h-5 text-gray-400 shrink-0"></i>
          </button>
          <div class="accordion-content px-5 md:px-6 pb-0">
            <p class="text-gray-600 leading-relaxed pl-0 md:pl-15">Training individuals, families, and organizations to prepare for and respond to emergencies through workshops, certification courses, and community drills.</p>
          </div>
        </div>
        <!-- Program 4 -->
        <div class="program-item bg-white rounded-xl border border-gray-200 overflow-hidden">
          <button onclick="toggleAccordion(this)" class="w-full flex items-center gap-4 p-5 md:p-6 text-left hover:bg-gray-50 transition-colors" aria-expanded="false">
            <div class="program-icon w-11 h-11 rounded-lg bg-brand-red-light flex items-center justify-center shrink-0">
              <i data-lucide="globe" class="w-5 h-5 text-brand-red"></i>
            </div>
            <span class="font-heading font-700 text-lg text-brand-navy flex-1">International Humanitarian Aid</span>
            <i data-lucide="chevron-down" class="accordion-icon w-5 h-5 text-gray-400 shrink-0"></i>
          </button>
          <div class="accordion-content px-5 md:px-6 pb-0">
            <p class="text-gray-600 leading-relaxed pl-0 md:pl-15">Partnering with a global network of humanitarian organizations to deliver relief and recovery programs in conflict zones and disaster-affected regions worldwide.</p>
          </div>
        </div>
        <!-- Program 5 -->
        <div class="program-item bg-white rounded-xl border border-gray-200 overflow-hidden">
          <button onclick="toggleAccordion(this)" class="w-full flex items-center gap-4 p-5 md:p-6 text-left hover:bg-gray-50 transition-colors" aria-expanded="false">
            <div class="program-icon w-11 h-11 rounded-lg bg-brand-red-light flex items-center justify-center shrink-0">
              <i data-lucide="heart-pulse" class="w-5 h-5 text-brand-red"></i>
            </div>
            <span class="font-heading font-700 text-lg text-brand-navy flex-1">Community Health</span>
            <i data-lucide="chevron-down" class="accordion-icon w-5 h-5 text-gray-400 shrink-0"></i>
          </button>
          <div class="accordion-content px-5 md:px-6 pb-0">
            <p class="text-gray-600 leading-relaxed pl-0 md:pl-15">Providing health and safety education, disease prevention programs, and support services to underserved communities, including mental health resources for disaster survivors.</p>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- ========== GET INVOLVED ========== -->
  <section id="get-involved" class="py-20 md:py-28 bg-white">
    <div class="max-w-7xl mx-auto px-6 fade-in-up">
      <div class="text-center mb-12">
        <h2 class="font-heading font-700 text-3xl md:text-4xl text-brand-navy mb-4">Get Involved</h2>
        <p class="text-gray-500 max-w-xl mx-auto">Every act of generosity matters. Here's how you can make a difference today.</p>
      </div>
      <div class="grid md:grid-cols-3 gap-6 lg:gap-8">
        <!-- Volunteer -->
        <div class="group bg-brand-gray-warm rounded-2xl p-7 md:p-8 hover:shadow-lg hover:-translate-y-1 transition-all duration-300">
          <div class="w-14 h-14 rounded-xl bg-brand-navy flex items-center justify-center mb-5 group-hover:bg-brand-red transition-colors">
            <i data-lucide="users" class="w-7 h-7 text-white"></i>
          </div>
          <h3 class="font-heading font-700 text-xl text-brand-navy mb-3">Volunteer With Us</h3>
          <p class="text-gray-500 text-sm leading-relaxed mb-5">Join over 50,000 volunteers who give their time and skills to help people in need. Whether you can commit a few hours a month or deploy to a disaster zone, there's a role for you.</p>
          <a href="#" class="inline-flex items-center gap-1.5 text-brand-red font-semibold text-sm hover:gap-2.5 transition-all">
            Find Volunteer Opportunities <i data-lucide="arrow-right" class="w-4 h-4"></i>
          </a>
        </div>
        <!-- Fundraiser -->
        <div class="group bg-brand-gray-warm rounded-2xl p-7 md:p-8 hover:shadow-lg hover:-translate-y-1 transition-all duration-300">
          <div class="w-14 h-14 rounded-xl bg-brand-navy flex items-center justify-center mb-5 group-hover:bg-brand-red transition-colors">
            <i data-lucide="megaphone" class="w-7 h-7 text-white"></i>
          </div>
          <h3 class="font-heading font-700 text-xl text-brand-navy mb-3">Start a Fundraiser</h3>
          <p class="text-gray-500 text-sm leading-relaxed mb-5">Rally your community, workplace, or school to raise funds for disaster relief. We provide toolkits and support to help you make the biggest impact.</p>
          <a href="#" class="inline-flex items-center gap-1.5 text-brand-red font-semibold text-sm hover:gap-2.5 transition-all">
            Start Your Fundraiser <i data-lucide="arrow-right" class="w-4 h-4"></i>
          </a>
        </div>
        <!-- Give Blood -->
        <div class="group bg-brand-gray-warm rounded-2xl p-7 md:p-8 hover:shadow-lg hover:-translate-y-1 transition-all duration-300">
          <div class="w-14 h-14 rounded-xl bg-brand-navy flex items-center justify-center mb-5 group-hover:bg-brand-red transition-colors">
            <i data-lucide="droplets" class="w-7 h-7 text-white"></i>
          </div>
          <h3 class="font-heading font-700 text-xl text-brand-navy mb-3">Give Blood</h3>
          <p class="text-gray-500 text-sm leading-relaxed mb-5">Every two seconds, someone in the country needs blood. Schedule an appointment at a blood drive near you and help save lives.</p>
          <a href="#" class="inline-flex items-center gap-1.5 text-brand-red font-semibold text-sm hover:gap-2.5 transition-all">
            Find a Blood Drive <i data-lucide="arrow-right" class="w-4 h-4"></i>
          </a>
        </div>
      </div>
    </div>
  </section>

  <!-- ========== NEWS ========== -->
  <section id="news" class="py-20 md:py-28 bg-brand-gray-warm">
