  <script>
    // Initialize Lucide icons
    lucide.createIcons();

    // ---- HEADER SCROLL ----
    const header = document.getElementById('site-header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('header-scrolled', window.scrollY > 20);
    });

    // ---- MOBILE MENU ----
    let mobileOpen = false;
    function toggleMobileMenu() {
      mobileOpen = !mobileOpen;
      document.getElementById('mobile-menu').classList.toggle('open', mobileOpen);
      document.getElementById('mobile-overlay').classList.toggle('open', mobileOpen);
      document.body.style.overflow = mobileOpen ? 'hidden' : '';
    }

    // ---- DONATE MODAL ----
    let selectedAmount = 100;
    const impactMap = {
      25: 'Provides 5 emergency blankets for displaced families',
      50: 'Supplies a family with food and water for one week',
      100: 'Funds emergency shelter materials for a household',
      250: 'Equips a volunteer with disaster response training',
      500: 'Provides critical medical supplies for a field hospital',
    };

    function openDonateModal() {
      const modal = document.getElementById('donate-modal');
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
      lucide.createIcons();
    }

    function closeDonateModal() {
      const modal = document.getElementById('donate-modal');
      modal.classList.remove('open');
      document.body.style.overflow = '';
    }

    // Amount buttons
    document.querySelectorAll('.amount-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
        btn.classList.add('selected');
        const amt = btn.dataset.amount;
        const customField = document.getElementById('custom-amount-field');
        const impactText = document.getElementById('impact-text');

        if (amt === 'custom') {
          customField.classList.remove('hidden');
          impactText.textContent = 'Every dollar counts toward saving lives';
          selectedAmount = null;
        } else {
          customField.classList.add('hidden');
          selectedAmount = parseInt(amt);
          impactText.textContent = impactMap[selectedAmount] || 'Every dollar counts toward saving lives';
        }
      });
    });

    // Donation type toggle
    document.querySelectorAll('.donation-type-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.donation-type-btn').forEach(b => {
          b.classList.remove('bg-white', 'shadow', 'text-brand-navy');
          b.classList.add('text-gray-500');
        });
        btn.classList.add('bg-white', 'shadow', 'text-brand-navy');
        btn.classList.remove('text-gray-500');
      });
    });

    // Close modal on backdrop click
    document.getElementById('donate-modal').addEventListener('click', (e) => {
      if (e.target === e.currentTarget) closeDonateModal();
    });

    // Close modal on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (document.getElementById('donate-modal').classList.contains('open')) closeDonateModal();
        if (mobileOpen) toggleMobileMenu();
      }
    });

    function submitDonation() {
      const amount = selectedAmount || document.getElementById('custom-amount-input').value;
      if (!amount || amount <= 0) {
        document.getElementById('custom-amount-input').focus();
        return;
      }
      alert(`Thank you for your $${amount} donation! This is a demo — no payment was processed.`);
      closeDonateModal();
    }

    // ---- ACCORDION ----
    function toggleAccordion(button) {
      const content = button.nextElementSibling;
      const icon = button.querySelector('.accordion-icon');
      const isOpen = content.classList.contains('open');

      // Close all
      document.querySelectorAll('.accordion-content').forEach(c => c.classList.remove('open'));
      document.querySelectorAll('.accordion-icon').forEach(i => i.classList.remove('rotated'));
      document.querySelectorAll('.program-item button').forEach(b => b.setAttribute('aria-expanded', 'false'));

      // Open clicked if was closed
      if (!isOpen) {
        content.classList.add('open');
        icon.classList.add('rotated');
        button.setAttribute('aria-expanded', 'true');
      }
    }

    // ---- NEWS CAROUSEL ----
    let carouselIndex = 0;
    const track = document.getElementById('carousel-track');

    function getVisibleCards() {
      const w = window.innerWidth;
      if (w >= 1024) return 3;
      if (w >= 640) return 2;
      return 1;
    }

    function getMaxIndex() {
      const total = track.children.length;
      return Math.max(0, total - getVisibleCards());
    }

    function updateCarousel() {
      const card = track.children[0];
      if (!card) return;
      const gap = 24;
      const cardWidth = card.offsetWidth + gap;
      track.style.transform = `translateX(-${carouselIndex * cardWidth}px)`;
    }

    function carouselNext() {
      carouselIndex = Math.min(carouselIndex + 1, getMaxIndex());
      updateCarousel();
    }

    function carouselPrev() {
      carouselIndex = Math.max(carouselIndex - 1, 0);
      updateCarousel();
    }

    window.addEventListener('resize', () => {
      carouselIndex = Math.min(carouselIndex, getMaxIndex());
      updateCarousel();
    });

    // ---- ANIMATED COUNTERS ----
    function animateCounters() {
      document.querySelectorAll('.stat-number').forEach(el => {
        const target = parseInt(el.dataset.target);
        const suffix = el.dataset.suffix || '';
        const prefix = el.dataset.prefix || '';
        const duration = 2000;
        const start = performance.now();

        function update(now) {
          const elapsed = now - start;
          const progress = Math.min(elapsed / duration, 1);
          // Ease out cubic
          const eased = 1 - Math.pow(1 - progress, 3);
          const current = Math.round(eased * target);
          el.textContent = prefix + current.toLocaleString() + suffix;
          if (progress < 1) requestAnimationFrame(update);
        }
        requestAnimationFrame(update);
      });
    }

    // ---- SCROLL ANIMATIONS ----
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');

          // Trigger counter animation when stats section is visible
          if (entry.target.closest('#impact-stats')) {
            animateCounters();
          }

          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15 });

    document.querySelectorAll('.fade-in-up').forEach(el => observer.observe(el));

    // Also observe the stats section directly
    const statsSection = document.getElementById('impact-stats');
    if (statsSection) {
      const statsObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            animateCounters();
            statsObserver.unobserve(entry.target);
          }
        });
      }, { threshold: 0.2 });
      statsObserver.observe(statsSection);
    }
  </script>
